svg.script:
// A framed diagram reports chapter changes from its own animation clock.
if (window.parent !== window) {
  const svg = document.documentElement;
  // Image embeds use the two symbols without script. In the interactive
  // frame, render their geometry directly so entrance styles reach each
  // component and both layouts keep the root SVG's single payload clock.
  const viewBoxes = {};
  for (const instance of svg.querySelectorAll(':scope > use')) {
    const layout = instance.getAttribute('class');
    const symbol = svg.querySelector(instance.getAttribute('href'));
    viewBoxes[layout] = symbol.getAttribute('viewBox');
    const group = document.createElementNS(svg.namespaceURI, 'g');
    group.id = symbol.id;
    group.setAttribute('class', layout);
    group.append(...symbol.childNodes);
    symbol.remove();
    instance.replaceWith(group);
  }
  const portrait = matchMedia('(max-aspect-ratio: 1/1)');
  const fitLayout = () => svg.setAttribute('viewBox', portrait.matches ? viewBoxes.portrait : viewBoxes.wide);
  portrait.addEventListener('change', fitLayout);
  fitLayout();
  const cycle = svg.querySelector('animate[dur]').getSimpleDuration();
  svg.classList.add('how-motion');
  for (const route of svg.querySelectorAll('.entry-route')) {
    const path = svg.querySelector(route.getAttribute('href'));
    route.style.setProperty('--len', Math.ceil(path.getTotalLength()));
  }
  let timer;
  let lastStage = -1;
  svg.pauseAnimations();
  svg.setAttribute('data-paused', '');

  window.addEventListener('message', event => {
    const command = event.data;
    if (event.source !== parent || command?.type !== 'tellistic-playback') return;
    clearTimeout(timer);
    const {playing, drawing, starts, seekTo} = command;
    svg.classList.toggle('is-drawing', drawing);
    if (Number.isFinite(seekTo) && starts.includes(seekTo)) {
      svg.setCurrentTime(seekTo);
      lastStage = -1;
    }
    if (playing) svg.unpauseAnimations();
    else svg.pauseAnimations();
    svg.toggleAttribute('data-paused', !playing);

    function report() {
      const time = svg.getCurrentTime() % cycle;
      const next = starts.findIndex(start => start > time);
      const stage = (next === -1 ? starts.length : next) - 1;
      if (stage !== lastStage) {
        parent.postMessage({type: 'tellistic-stage', stage}, '*');
        lastStage = stage;
      }
      if (playing) {
        const boundary = next === -1 ? cycle : starts[next];
        timer = setTimeout(report, Math.max(30, (boundary - time) * 1000 + 16));
      }
    }
    report();
  });
  parent.postMessage({type: 'tellistic-ready'}, '*');
}
